package ec.edu.scli.reservas.infrastructure.persistence.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="registros_asistencia", uniqueConstraints=@UniqueConstraint(columnNames={"sesion_id","estudiante_id"})) public class RegistroAsistenciaJpaEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="sesion_id") private UUID sesionId; private UUID estudianteId; private Instant registradaEn; private String estado="PRESENTE"; public UUID getId(){return id;} public void setId(UUID v){id=v;} public UUID getSesionId(){return sesionId;} public void setSesionId(UUID v){sesionId=v;} public UUID getEstudianteId(){return estudianteId;} public void setEstudianteId(UUID v){estudianteId=v;} public Instant getRegistradaEn(){return registradaEn;} public void setRegistradaEn(Instant v){registradaEn=v;} public String getEstado(){return estado;} public void setEstado(String v){estado=v;} }
